CREATE TABLE IF NOT EXISTS sect (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(32) NOT NULL, leader_uid INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_sect_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sect_member (id BIGINT NOT NULL AUTO_INCREMENT, sect_id BIGINT NOT NULL, uid INT NOT NULL, role VARCHAR(16) NOT NULL DEFAULT '成员', contribution INT NOT NULL DEFAULT 0, member_state VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_sect_member(sect_id, uid), KEY idx_sect_member_uid(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sect_vote (id BIGINT NOT NULL AUTO_INCREMENT, sect_id BIGINT NOT NULL, uid INT NOT NULL, week_key VARCHAR(16) NOT NULL, research_type VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_sect_vote(sect_id, uid, week_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sect_research (id BIGINT NOT NULL AUTO_INCREMENT, sect_id BIGINT NOT NULL, week_key VARCHAR(16) NOT NULL, research_type VARCHAR(16) NOT NULL, vote_count INT NOT NULL DEFAULT 0, settled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_sect_research(sect_id, week_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sect_task_log (id BIGINT NOT NULL AUTO_INCREMENT, sect_id BIGINT NOT NULL, uid INT NOT NULL, task_date DATE NOT NULL, contribution INT NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_sect_task(sect_id, uid, task_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS master_apprentice (id BIGINT NOT NULL AUTO_INCREMENT, master_uid INT NOT NULL, apprentice_uid INT NOT NULL, state VARCHAR(16) NOT NULL, progress INT NOT NULL DEFAULT 0, target_progress INT NOT NULL DEFAULT 7, accepted_at DATETIME NULL, last_active_at DATETIME NULL, PRIMARY KEY(id), KEY idx_master_apprentice(master_uid, state), KEY idx_apprentice(apprentice_uid, state)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
